∀ {Role : Type u} {bound : ℕ} {owner : Role} {Action : Type v} {nonempty : Nonempty Action}
  {next : Action → KFOL.Strategic.QuantifiedTree Role} {support : Finset Action} {inhabited : Nonempty ↥support}
  {small : support.card ≤ bound} {children : ↥support → KFOL.Strategic.QuantifiedTree Role}
  {sub : ∀ (a : ↥support), KFOL.Strategic.QuantifiedTree.Prunes bound (next ↑a) (children a)},
  (KFOL.Strategic.QuantifiedTree.node owner (↥support) inhabited children).possibleWinners =
      (KFOL.Strategic.QuantifiedTree.node owner Action nonempty next).possibleWinners →
    (∀ (a : ↥support), ⋯.PreservesValues) → ⋯.PreservesValues

